+WSLUA_METAMETHOD ProtoField_get_valuestring(lua_State* L) {
+    ProtoField f = checkProtoField(L,1);
+    if (f->valuestring_ref != LUA_NOREF) {
+        lua_rawgeti(L, LUA_REGISTRYINDEX, f->valuestring_ref);
+    } else {
+        lua_pushnil(L);
+    }
+    return 1;
+}
